import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForMag1,validMag1,advanceMag1,numericMag1,experimentOptions,experimentResult,experimentCases,experimentValid,predictionValid,outputLabel}from './mag1-models.js?v=20261023-physicscomplete01';import{showMag1}from './mag1-visuals.js?v=20261023-physicscomplete01';export{showMag1};
export function mountMag1(l,p,root,{save,done,feedback}){let ts=tasksForMag1(l.widget.slice(5),l.learnerTier),w=p.widget;w.mag1Task??=ts[0].id;w.mag1Drafts??={};w.mag1Passed??=[];let i=ts.findIndex(t=>t.id===w.mag1Task);if(i<0)i=0;let t=ts[i],v=w.mag1Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountMag1(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.mag1Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('mag1Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('mag1Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealMag1">Reveal evidence →</button><p id="mag1Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showMag1(t.kind,{state:c[0],context:'comparison',title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#mag1Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validMag1(c,v.answer);}
else if(t.type==='sequence'){body=field('mag1Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceMag1">Advance pathway →</button><p id="mag1Readout" aria-live="polite"></p>';draw=()=>{showMag1(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#mag1Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('mag1A',o.labels[0],o.a,v.a)+field('mag1B',o.labels[1],o.b,v.b)+(o.choices?field('mag1Prediction','Predict / '+o.unit,o.choices,v.prediction):'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="mag1Prediction" value="'+(v.prediction??'')+'"></label>')+'<button class="secondary" id="mag1Run">Reveal model output →</button><p id="mag1Output"></p>'+field('mag1Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showMag1(t.kind,{a:v.a,b:v.b,wiring:v.wiring,revealed:v.ran,title:t.title});$('#mag1Output').textContent=v.ran?'Model output: '+outputLabel(t.experiment,r.value):'Predict first. Use the selected quantities and the relationship explained in Discover.';};valid=()=>!!v.ran&&predictionValid(t.experiment,v.prediction,experimentResult(t.experiment,v.a,v.b));}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="mag1Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="mag1Number" type="number" step="any" value="'+(v.number??'')+'">'+field('mag1Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showMag1(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericMag1(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="mag1Evidence"></p><div class="lab-actions"><button class="secondary" id="recordMag1">Record reasoning</button><button class="secondary" id="nextMag1">Next challenge →</button></div><p id="mag1Progress"></p>';
const status=()=>{$('#mag1Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.mag1Passed.includes(t.id)?'Challenge recorded.':'';$('#mag1Progress').textContent=ts.filter(t=>w.mag1Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='mag1A'||id==='mag1B'){if(!val){remount();return;}v[id==='mag1A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='mag1Interpretation'){v.interpretation=val;save();return;}if(id==='mag1Prediction'){v.prediction=val;save();return;}if(id==='mag1Case'){if(val===''){remount();return;}v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='mag1Answer')v.answer=val;else if(id==='mag1Next')v.next=val;else if(id==='mag1Number')v.number=val;else if(id==='mag1Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='mag1Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#mag1Run'))$('#mag1Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Make a prediction first.',true);return;}v.ran=true;save();draw();};
if($('#revealMag1'))$('#revealMag1').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validMag1(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validMag1(t.cases[v.case],v.answer));};
if($('#advanceMag1'))$('#advanceMag1').onclick=()=>{let n=advanceMag1(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordMag1').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.mag1Passed.includes(t.id))w.mag1Passed.push(t.id);p.widgetDone=ts.every(t=>w.mag1Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All required settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextMag1').onclick=()=>{if(!w.mag1Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.mag1Task=ts[(i+1)%ts.length].id;save();remount();};}
